"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[83989],{28453:(e,n,i)=>{i.d(n,{R:()=>o,x:()=>r});var a=i(96540);const t={},s=a.createContext(t);function o(e){const n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:o(e.components),a.createElement(s.Provider,{value:n},e.children)}},35504:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/08/14/hudi-for-read-heavy-workloads-point-lookups-with-indexes","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-08-14-hudi-for-read-heavy-workloads-point-lookups-with-indexes.md","source":"@site/blog/2026-08-14-hudi-for-read-heavy-workloads-point-lookups-with-indexes.md","title":"Point Lookups on the Lakehouse: How Hudi Indexes Accelerate Read-Heavy Workloads","description":"How Apache Hudi\'s record-level, secondary, and expression indexes prune files at query planning time to accelerate point lookups and selective reads.","date":"2026-08-14T00:00:00.000Z","tags":[{"inline":true,"label":"indexing","permalink":"/blog/tags/indexing"},{"inline":true,"label":"performance","permalink":"/blog/tags/performance"},{"inline":true,"label":"querying","permalink":"/blog/tags/querying"},{"inline":true,"label":"data skipping","permalink":"/blog/tags/data-skipping"}],"readingTime":13.45,"hasTruncateMarker":false,"authors":[{"name":"Sivabalan Narayanan","url":"https://www.linkedin.com/in/sivabalan-narayanan-1040b45/","imageURL":"/assets/images/authors/sivabalan.jpg","key":"sivabalan","page":null}],"frontMatter":{"title":"Point Lookups on the Lakehouse: How Hudi Indexes Accelerate Read-Heavy Workloads","excerpt":"Partition pruning and min/max file statistics stop helping when queries filter on high-cardinality columns. Hudi\'s record-level, secondary, and expression indexes prune point lookups down to the handful of files that actually contain matching rows.","description":"How Apache Hudi\'s record-level, secondary, and expression indexes prune files at query planning time to accelerate point lookups and selective reads.","authors":["sivabalan"],"category":"deep-dive","image":"/assets/images/blog/2024-03-30-record-level-indexing-apache-hudi-delivers-70-faster-point.png","tags":["indexing","performance","querying","data skipping"]},"unlisted":false,"lastUpdatedAt":1786488307000,"nextItem":{"title":"Apache Hudi vs Apache Iceberg Performance: What Benchmarks Show, and What We Measured","permalink":"/blog/2026/08/13/hudi-vs-iceberg-performance-benchmarks"}}')},67039:(e,n,i)=>{i.r(n),i.d(n,{assets:()=>d,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>a,toc:()=>l});var a=i(35504),t=i(74848),s=i(28453);const o={title:"Point Lookups on the Lakehouse: How Hudi Indexes Accelerate Read-Heavy Workloads",excerpt:"Partition pruning and min/max file statistics stop helping when queries filter on high-cardinality columns. Hudi's record-level, secondary, and expression indexes prune point lookups down to the handful of files that actually contain matching rows.",description:"How Apache Hudi's record-level, secondary, and expression indexes prune files at query planning time to accelerate point lookups and selective reads.",authors:["sivabalan"],category:"deep-dive",image:"/assets/images/blog/2024-03-30-record-level-indexing-apache-hudi-delivers-70-faster-point.png",tags:["indexing","performance","querying","data skipping"]},r=void 0,d={authorsImageUrls:[void 0]},l=[{value:"Why Selective Queries Are Hard on a Data Lake",id:"why-selective-queries-are-hard-on-a-data-lake",level:2},{value:"How Hudi Indexes Serve Reads",id:"how-hudi-indexes-serve-reads",level:2},{value:"Using It from Spark SQL",id:"using-it-from-spark-sql",level:2},{value:"What About Trino?",id:"what-about-trino",level:2},{value:"What Published Results Show",id:"what-published-results-show",level:2},{value:"How This Compares Architecturally",id:"how-this-compares-architecturally",level:2},{value:"Operational Notes",id:"operational-notes",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function c(e){const n={a:"a",code:"code",em:"em",h2:"h2",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,s.R)(),...e.components},{PostFAQ:i}=n;return i||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,t.jsxs)(t.Fragment,{children:[(0,t.jsxs)(n.p,{children:["Analytical scans are not the only workload a lakehouse table serves. In many production query mixes, a large share of queries are needle-in-haystack reads: fetch one order by ",(0,t.jsx)(n.code,{children:"order_id"}),", pull a user's profile by ",(0,t.jsx)(n.code,{children:"user_id"}),", trace a request by ",(0,t.jsx)(n.code,{children:"uuid"}),", list all events for one ",(0,t.jsx)(n.code,{children:"customer_id"}),". These queries touch a few rows out of billions \u2014 and they are exactly where the lake's two standard pruning tools, partition pruning and min/max file statistics, stop helping. Apache Hudi answers this with queryable indexes maintained inside its ",(0,t.jsx)(n.a,{href:"/docs/metadata",children:"metadata table"}),": a record-level index that maps each record key to its file group, secondary indexes that map non-key column values to record keys, expression indexes over transformed columns, and centrally stored bloom filters. At query planning time, these indexes prune the scan down to the few files that actually contain matching rows. The effect is not subtle: on a 400 GB table with 20,000 file groups, a record-key lookup published in ",(0,t.jsx)(n.a,{href:"/blog/2025/11/12/deep-dive-into-hudis-indexing-subsystem-part-2-of-2",children:"Hudi's indexing deep-dive series"})," dropped from 977 seconds to 12 seconds once the record index was in play."]}),"\n",(0,t.jsxs)(n.p,{children:["This post is the read-side companion to our ",(0,t.jsx)(n.a,{href:"/blog/2026/08/12/hudi-vs-delta-lake-for-write-heavy-workloads",children:"write-heavy comparison"}),". Same approach: mechanisms first, and only benchmark numbers that have already been published, with dates and sources."]}),"\n",(0,t.jsx)(n.h2,{id:"why-selective-queries-are-hard-on-a-data-lake",children:"Why Selective Queries Are Hard on a Data Lake"}),"\n",(0,t.jsx)(n.p,{children:"Lakehouse tables are laid out for scans: large immutable columnar files, grouped into partitions, described by file-level statistics. Every standard read optimization prunes at one of those granularities, and each one has a blind spot for selective predicates on high-cardinality columns:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Partition pruning"})," only helps if the filter column is the partition column. Nobody partitions by ",(0,t.jsx)(n.code,{children:"user_id"})," or ",(0,t.jsx)(n.code,{children:"uuid"})," \u2014 the cardinality is far too high \u2014 so a point lookup on such a column matches ",(0,t.jsx)(n.em,{children:"every"})," partition."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Min/max file statistics"}),' help when values correlate with file layout. A filter on an ingestion timestamp prunes beautifully, because each file covers a narrow time range. But a random key like a UUID is uniformly spread: every file\'s min/max range spans nearly the whole keyspace, so every file "might" contain the value and nothing is pruned. Sorting or clustering the data can rescue statistics for ',(0,t.jsx)(n.em,{children:"one"})," column, but a table can only be physically ordered one way."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Parquet footer bloom filters and page indexes"})," operate per file \u2014 the engine still has to open every candidate file to consult them, which at thousands of files is itself the bottleneck."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["The result is familiar to anyone who has run ",(0,t.jsx)(n.code,{children:"SELECT * FROM events WHERE request_id = '...'"}),' on a large table: a full scan of the key column across the table, minutes of compute, and (on scan-priced engines) a bill proportional to table size rather than result size. What the query needed was a database-style answer to "which files contain this value?" \u2014 an index.']}),"\n",(0,t.jsx)(n.h2,{id:"how-hudi-indexes-serve-reads",children:"How Hudi Indexes Serve Reads"}),"\n",(0,t.jsxs)(n.p,{children:["Hudi has maintained indexes since its inception, originally to make upserts and deletes fast \u2014 the write side of the same problem, as covered in the ",(0,t.jsx)(n.a,{href:"/blog/2026/08/12/hudi-vs-delta-lake-for-write-heavy-workloads",children:"write-heavy post"}),". With the ",(0,t.jsx)(n.a,{href:"/docs/indexes#multi-modal-indexing",children:"multi-modal indexing subsystem"}),", those same structures are consulted at ",(0,t.jsx)(n.em,{children:"query planning time"}),". The indexes live as partitions of Hudi's metadata table \u2014 itself a Merge-on-Read Hudi table using an HFile format optimized for point lookups \u2014 and are updated transactionally with every commit, so index results are always consistent with the data. The read-relevant ones:"]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Record-level index (RLI)"})," \u2014 an exact mapping from record key to file location, hash-sharded across file groups to scale to very large keyspaces. A query with an equality predicate on the record key (",(0,t.jsx)(n.code,{children:"WHERE uuid = '...'"}),") resolves directly to the file group holding that key; only that file is scanned."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Secondary index"})," \u2014 introduced in ",(0,t.jsx)(n.a,{href:"/blog/2025/04/02/secondary-index",children:"Hudi 1.0"}),", an index on any non-key column. It maps secondary key values (e.g., ",(0,t.jsx)(n.code,{children:"city"}),", ",(0,t.jsx)(n.code,{children:"driver"}),", ",(0,t.jsx)(n.code,{children:"customer_id"}),") to the record keys that carry them; the record index then maps those keys to file locations. Equality and ",(0,t.jsx)(n.code,{children:"IN"})," predicates on indexed columns prune to exactly the files containing matches."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Expression index"})," \u2014 an index on a ",(0,t.jsx)(n.em,{children:"function"})," of a column, in two flavors: column-stats over transformed values (e.g., ",(0,t.jsx)(n.code,{children:"from_unixtime(ts)"})," for date filters on epoch columns) and bloom filters over transformed values for equality matching on high-cardinality columns."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Bloom filter index"})," \u2014 bloom filters for all data files stored centrally in the metadata table, so candidate files can be eliminated without touching each file's footer."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Column stats and partition stats indexes"})," \u2014 the min/max statistics story, but stored in the scalable metadata table and usable for range predicates and partition-level skipping."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["The planning flow for a secondary-index lookup, as described in the ",(0,t.jsx)(n.a,{href:"/blog/2025/11/12/deep-dive-into-hudis-indexing-subsystem-part-2-of-2",children:"indexing deep dive"}),": the engine pushes the equality predicate down to Hudi's integration layer, the secondary index returns the matching record keys, the record index returns the enclosing file locations, and the engine plans a scan over just those files. Two point lookups against compact metadata replace a scan over the table \u2014 the same shape a database index lookup takes, running over lake storage."]}),"\n",(0,t.jsxs)(n.p,{children:["This combination of write-side and read-side indexing is one of the ",(0,t.jsx)(n.a,{href:"/blog/2025/03/05/hudi-21-unique-differentiators",children:"things that distinguish Hudi architecturally"}),": the storage format deliberately spends extra space on indexes to serve both record-level mutation and selective reads, rather than optimizing for vanilla scans alone."]}),"\n",(0,t.jsx)(n.h2,{id:"using-it-from-spark-sql",children:"Using It from Spark SQL"}),"\n",(0,t.jsxs)(n.p,{children:["Index-accelerated reads are plain SQL. Create a table with the record index enabled (secondary indexes require it, along with a primary key and the ",(0,t.jsx)(n.code,{children:"COMMIT_TIME_ORDERING"})," merge mode), then create indexes with ",(0,t.jsx)(n.code,{children:"CREATE INDEX"}),":"]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-sql",children:"CREATE TABLE hudi_table (\n    ts BIGINT,\n    uuid STRING,\n    rider STRING,\n    driver STRING,\n    fare DOUBLE,\n    city STRING\n) USING hudi\nOPTIONS (\n    primaryKey = 'uuid',\n    hoodie.metadata.record.index.enable = 'true',\n    hoodie.write.record.merge.mode = 'COMMIT_TIME_ORDERING'\n)\nPARTITIONED BY (city);\n\n-- record index first; secondary indexes build on it\nCREATE INDEX record_index ON hudi_table (uuid);\n-- secondary index on a non-key, high-cardinality column\nCREATE INDEX idx_rider ON hudi_table (rider);\n"})}),"\n",(0,t.jsx)(n.p,{children:"Queries need no hints \u2014 equality predicates on indexed columns are pruned automatically during planning:"}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-sql",children:"-- point lookup on the record key, served by the record-level index\nSELECT * FROM hudi_table\nWHERE uuid = 'c8abbe79-8d89-47ea-b4ce-4d224bae5bfa';\n\n-- selective filter on a non-key column, served by the secondary index\nSELECT * FROM hudi_table WHERE rider = 'rider-B';\n"})}),"\n",(0,t.jsxs)(n.p,{children:["In the walkthrough in the ",(0,t.jsx)(n.a,{href:"/docs/sql_queries",children:"SQL queries documentation"}),", the second query scans one file instead of three after the index is created \u2014 on the toy table that is the whole point demonstrated; on production tables the pruning ratio scales with file count. Expression indexes cover predicates with inline transformations, and bloom-filter expression indexes handle equality matching where an exact mapping would be overkill:"]}),"\n",(0,t.jsx)(n.pre,{children:(0,t.jsx)(n.code,{className:"language-sql",children:"-- date filters on an epoch column\nCREATE INDEX idx_column_ts ON hudi_table\n  USING column_stats(ts) OPTIONS(expr='from_unixtime', format='yyyy-MM-dd');\n\n-- bloom-filter pruning for equality predicates on driver\nCREATE INDEX idx_bloom_driver ON hudi_table\n  USING bloom_filters(driver) OPTIONS(expr='identity');\n"})}),"\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.code,{children:"SHOW INDEXES FROM hudi_table"})," lists what exists, ",(0,t.jsx)(n.code,{children:"DROP INDEX"})," removes one, and session settings such as ",(0,t.jsx)(n.code,{children:"SET hoodie.metadata.record.index.enable=true"})," and ",(0,t.jsx)(n.code,{children:"SET hoodie.metadata.column.stats.enable=true"})," control which indexes the reader consults \u2014 see ",(0,t.jsx)(n.a,{href:"/docs/sql_queries",children:"SQL queries"})," for the full set."]}),"\n",(0,t.jsx)(n.h2,{id:"what-about-trino",children:"What About Trino?"}),"\n",(0,t.jsxs)(n.p,{children:["Honestly stated: index-based pruning through the record-level, secondary, and expression indexes is a ",(0,t.jsx)(n.strong,{children:"Spark SQL capability today"}),". When secondary indexes shipped in Hudi 1.0, ",(0,t.jsx)(n.a,{href:"/blog/2025/04/02/secondary-index",children:"support was planned for Flink, Presto, and Trino"})," in a subsequent release; that work rides on the fact that the indexes are engine-neutral storage structures \u2014 partitions of the metadata table on disk, not Spark-private state \u2014 so an engine integration implements the lookup against index data that is already there."]}),"\n",(0,t.jsxs)(n.p,{children:["What Trino supports today, per the ",(0,t.jsx)(n.a,{href:"/docs/sql_queries#trino",children:"query engine documentation"}),": Hudi tables are queried through the native Hudi connector (Trino 398 onward) or via the Hive connector with table redirection (Trino 411 onward, using ",(0,t.jsx)(n.code,{children:"hive.hudi-catalog-name=hudi"}),"). Both paths support snapshot queries on Copy-on-Write tables and read-optimized queries on Merge-on-Read tables, with MOR snapshot query support in progress in the Trino community. So a Trino-fronted deployment gets Hudi's transactional reads and columnar scan performance now, and a practical pattern for selective workloads is to route the highly selective lookups through Spark SQL (where index acceleration is live) while Trino serves the scan-shaped dashboards and ad-hoc analytics \u2014 converging on one engine story as connector-side index support lands."]}),"\n",(0,t.jsx)(n.h2,{id:"what-published-results-show",children:"What Published Results Show"}),"\n",(0,t.jsx)(n.p,{children:"Two data points, both from Hudi's own published material, both with setups disclosed:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Record-level index"})," (",(0,t.jsx)(n.a,{href:"/blog/2025/11/12/deep-dive-into-hudis-indexing-subsystem-part-2-of-2",children:"indexing deep dive, November 2025"}),"): on a 400 GB synthetic Hudi table with 20,000 file groups, a query filtering on a single record key dropped from 977 seconds to 12 seconds \u2014 a 98% reduction \u2014 with the record index in use."]}),"\n",(0,t.jsxs)(n.li,{children:[(0,t.jsx)(n.strong,{children:"Secondary index"})," (",(0,t.jsx)(n.a,{href:"/blog/2025/04/02/secondary-index",children:"secondary index announcement, April 2025"}),"): on the TPC-DS 1 TB dataset (Hudi 1.0.1, Spark 3.5.5 on EMR, 10 executors), a join query with a customer-id lookup on ",(0,t.jsx)(n.code,{children:"web_sales"})," ran ~33% faster on the first run and ~58% faster on a warm second run with a secondary index on ",(0,t.jsx)(n.code,{children:"ws_ship_customer_sk"}),". Data scanned fell ~90% \u2014 from 67 GB across 5,000 files to 7 GB across 521 files, and from 719M rows scanned to 75M."]}),"\n"]}),"\n",(0,t.jsxs)(n.p,{children:["The scan reduction is the number to internalize: latency gains vary with cluster and cache state, but reading 90% fewer bytes is an architectural outcome, and on engines priced per byte scanned it translates directly to cost. For reproducing this class of measurement on your own keys and data distribution, the open-source ",(0,t.jsx)(n.a,{href:"https://github.com/onehouseinc/lake-loader",children:"LakeLoader"})," framework exists precisely to generate controlled, repeatable lakehouse workloads."]}),"\n",(0,t.jsx)(n.h2,{id:"how-this-compares-architecturally",children:"How This Compares Architecturally"}),"\n",(0,t.jsxs)(n.p,{children:["Lakehouse table formats broadly take one of two positions on selective reads. One position is ",(0,t.jsx)(n.em,{children:"file-statistics-only pruning"}),": keep per-file min/max statistics (plus partition values) in table metadata, and make them effective by physically clustering data so that values correlate with files. This is metadata that is cheap to maintain and works well when queries filter on the clustering dimensions \u2014 but a table can only be clustered one way, and predicates on other high-cardinality columns degrade toward scanning the column across all files."]}),"\n",(0,t.jsxs)(n.p,{children:["Hudi's position is ",(0,t.jsx)(n.em,{children:"queryable index metadata"}),": spend additional storage and write-path work maintaining exact value-to-location mappings (record-level and secondary indexes) and auxiliary structures (bloom filters, expression indexes) in a scalable, transactionally-updated metadata table, so that pruning for equality predicates is an index lookup rather than a statistics estimate \u2014 on as many columns as you choose to index. The trade is explicit: index storage and maintenance cost in exchange for bounded lookup cost regardless of which column the predicate hits. For read-heavy workloads dominated by selective queries, that bound is what shows up in latency and scan bills; for purely scan-shaped workloads, statistics-based skipping (which Hudi also has, via column stats and partition stats) is sufficient for any format."]}),"\n",(0,t.jsx)(n.h2,{id:"operational-notes",children:"Operational Notes"}),"\n",(0,t.jsxs)(n.p,{children:["Two things keep this practical in production. First, indexes are maintained ",(0,t.jsx)(n.strong,{children:"transactionally with each commit"})," \u2014 a query planned against the secondary index sees results consistent with the latest completed write, not a lagging sidecar. Second, adding an index to a table that is already ingesting does not require stopping it: Hudi's ",(0,t.jsx)(n.a,{href:"/docs/metadata_indexing",children:"async indexing"})," builds a new index in the background while writers keep committing, then reconciles the seam \u2014 the mechanics and the architectural reasons it works are covered in ",(0,t.jsx)(n.a,{href:"/blog/2026/06/25/building-indexes-on-a-moving-target",children:"Building Indexes on a Moving Target"}),". Start with the record index for key lookups, add secondary indexes for the handful of non-key columns that appear in selective predicates (each adds maintenance cost, so index high-value columns, not everything), and use expression indexes where predicates transform columns inline."]}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,t.jsxs)(n.p,{children:["Point lookups and selective filters on high-cardinality columns are a real, often dominant slice of production query traffic, and they are precisely the queries that partition pruning and min/max statistics cannot save. Hudi's answer is the one databases settled on decades ago \u2014 indexes \u2014 rebuilt for lake storage as transactional partitions of a scalable metadata table: a record-level index for key equality, secondary indexes for non-key columns, expression indexes for transformed predicates, and centrally stored bloom filters, all consulted at query planning to shrink the scan to files that matter. From Spark SQL this is live today with plain ",(0,t.jsx)(n.code,{children:"CREATE INDEX"})," syntax; on Trino, Hudi serves fast transactional reads through its connector with index acceleration on the roadmap the community has published. Paired with the ",(0,t.jsx)(n.a,{href:"/blog/2026/08/12/hudi-vs-delta-lake-for-write-heavy-workloads",children:"write-side indexing story"}),", the same investment \u2014 a queryable index subsystem \u2014 pays on both halves of the workload: writes that scale with the change, and reads that scale with the result."]}),"\n",(0,t.jsx)(n.h2,{id:"faq",children:"FAQ"}),"\n",(0,t.jsx)(i,{heading:null,items:[{question:"Can you do point lookups on a data lake?",answer:"Yes, with a table format that maintains indexes. On a plain columnar lake, a point lookup on a high-cardinality column degrades to scanning that column across all files, because partition pruning and min/max statistics cannot narrow random key values. Apache Hudi maintains a record-level index mapping each record key to its file location and secondary indexes for non-key columns inside its metadata table, so an equality predicate resolves to the few files containing matches. A published example showed a record-key lookup on a 400 GB table dropping from 977 seconds to 12 seconds."},{question:"What is a secondary index in Apache Hudi?",answer:"A secondary index, introduced in Hudi 1.0, is an index on any column other than the record key. It stores mappings from secondary key values to record keys in the metadata table; at query time the matched record keys are resolved to file locations through the record-level index, and only those files are scanned. It is created with plain SQL, for example CREATE INDEX idx_city ON hudi_table(city), and requires the record index to be enabled on the table."},{question:"Does Trino use Hudi indexes?",answer:"Not yet for record-level and secondary index pruning \u2014 that acceleration is available from Spark SQL today. Trino queries Hudi tables through the native Hudi connector or Hive connector redirection, supporting snapshot queries on Copy-on-Write tables and read-optimized queries on Merge-on-Read tables. Because Hudi's indexes are engine-neutral structures stored in the metadata table rather than Spark-private state, engine integrations can adopt them, and support for Presto, Trino, and Flink was announced as planned when secondary indexes shipped."},{question:"How much faster are queries with Hudi's indexes?",answer:"Per Hudi's published measurements: a record-key lookup on a 400 GB synthetic table with 20,000 file groups fell from 977 seconds to 12 seconds with the record-level index (a 98% reduction), and a TPC-DS 1 TB join query with a customer-id filter ran about 33-58% faster with a secondary index while scanning roughly 90% less data \u2014 7 GB across 521 files instead of 67 GB across 5,000 files. Actual gains depend on data distribution and cluster setup, so test with your own workload."},{question:"Does maintaining indexes for reads slow down ingestion?",answer:"Indexes are updated transactionally with each commit, which adds bounded write-path work per index \u2014 one reason to index only the columns that appear in selective predicates. Adding a new index to a live table does not require stopping ingestion: Hudi's async indexing service builds the index in the background while writers keep committing, then reconciles concurrent changes, keeping the index timeline-consistent with the table."}]})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(c,{...e})}):c(e)}}}]);